import math


def _canon(L, w, n):
    # Estado canónico C_w: {L:'d', L+1:'a', L+w:'d'} en el tiempo 0.
    b = 2 * w - 3
    m = (math.isqrt(b * b + 4 * n) - b) // 2
    # Ajuste por si el piso cayó un paso corrido.
    while (m + 1) * (2 * w + m - 2) <= n:
        m += 1
    while m * (2 * w + m - 3) > n:
        m -= 1
    n -= m * (2 * w + m - 3)
    w += m
    R = L + w
    if n <= w - 2:
        return {L: 'd', L + 1 + n: 'a' if n % 2 == 0 else 'b', R: 'd'}
    if n == w - 1:
        return {L: 'd', R - 1: 'c', R: 'e'}
    return {L: 'd', L + 2 * w - 2 - n: 'c', R + 1: 'd'}


def predict(start, steps):
    if steps == 0:
        return dict(start)

    items = sorted(start.items())
    ds = [p for p, s in items if s == 'd']
    L, R = ds[0], ds[1]
    for p, s in items:
        if s != 'd':
            M, ch = p, s
            break
    w = R - L
    i = M - L
    t = steps

    # Casos especiales: se escapa una pared en el primer paso.
    if ch == 'b' and i == 1:
        if t <= w - 2:
            return {L + t + 1: 'a' if t % 2 else 'b', R: 'd'}
        if t == w - 1:
            return {R - 1: 'c', R: 'e'}
        return {R + 1: 'd', L + 2 * w - 2 - t: 'c'}

    if ch == 'c' and i == w - 1:
        if t <= w - 2:
            return {L: 'd', R - 1 - t: 'c'}
        u = t - (w - 1)
        return {L: 'd', L + 1 + u: 'a' if u % 2 == 0 else 'b'}

    # c viajando a la izquierda hasta tocar la pared izquierda.
    if ch == 'c':
        if t < i:
            return {L: 'd', M - t: 'c', R: 'd'}
        return _canon(L, w, t - i)

    # Ya estamos en el estado canónico.
    if ch == 'a' and i == 1:
        return _canon(L, w, t)

    # a o b viajando a la derecha, choque con la pared derecha y vuelta a canónico.
    hit = w - 1 - i
    if t <= hit:
        return {L: 'd', M + t: ch if t % 2 == 0 else ('a' if ch == 'b' else 'b'), R: 'd'}
    if t == hit + 1:
        return {L: 'd', R - 1: 'c', R: 'e'}
    back = 2 * w - i - 1
    if t < back:
        return {L: 'd', L + 2 * w - i - 1 - t: 'c', R + 1: 'd'}
    return _canon(L, w + 1, t - back)

